#import "BIPService.h"
#import <UIKit/UIKit.h>
#import <ImageIO/ImageIO.h>
#import <UniformTypeIdentifiers/UniformTypeIdentifiers.h>
#import <os/proc.h>
#import <CommonCrypto/CommonKeyDerivation.h>
#include "../Core/BIPCore.hpp"
#include "../Core/PixelCodec.hpp"
#include <memory>
#include <cmath>
#include <algorithm>
#include <tuple>
#include <cstring>
using namespace bip;
@implementation BIPOutput
- (instancetype)init {if((self=[super init])){_text=@"";_details=@"";}return self;}
@end
static Bytes dataBytes(NSData* d){auto p=static_cast<const uint8_t*>(d.bytes);return Bytes(p,p+d.length);}
static NSData* nsdata(const Bytes& b){return [NSData dataWithBytes:b.data() length:b.size()];}
static std::u16string utf16(NSString* s){std::u16string out(s.length,0);if(s.length)[s getCharacters:reinterpret_cast<unichar*>(out.data()) range:NSMakeRange(0,s.length)];return out;}
static void failure(NSError** error,const std::exception& e){if(error)*error=[NSError errorWithDomain:@"binary_image_passcode" code:1 userInfo:@{NSLocalizedDescriptionKey:[NSString stringWithUTF8String:e.what()]?:@"操作失败。"}];}
static bool pngData(NSData* data){const uint8_t sig[]={137,80,78,71,13,10,26,10};return data.length>=8&&memcmp(data.bytes,sig,8)==0;}
static void memoryCheck(uint64_t needed){uint64_t available=os_proc_available_memory();if(available&&needed>available*0.65)throw Error("当前内存不足以处理这张图片，请使用较小的底图或关闭其他应用后重试。");}
static CGImageSourceRef source(NSData* data){if(data.length>150*1024*1024)throw Error("图片文件最大150 MiB。");auto s=CGImageSourceCreateWithData((__bridge CFDataRef)data,nullptr);if(!s)throw Error("无法读取图片。请选择PNG、JPG、BMP、HEIF等受系统支持的静态图片。");return s;}
static std::tuple<int,int,int> dimensions(CGImageSourceRef s){NSDictionary* d=CFBridgingRelease(CGImageSourceCopyPropertiesAtIndex(s,0,nullptr));int w=[d[(__bridge NSString*)kCGImagePropertyPixelWidth] intValue],h=[d[(__bridge NSString*)kCGImagePropertyPixelHeight] intValue],o=[d[(__bridge NSString*)kCGImagePropertyOrientation] intValue];if(w<=0||h<=0)throw Error("图片尺寸无效。");return {w,h,o?o:1};}
static Pixels rendered(CGImageRef image,bool alpha){int w=int(CGImageGetWidth(image)),h=int(CGImageGetHeight(image));memoryCheck(uint64_t(w)*h*12);Bytes raw(size_t(w)*h*4);auto color=CGColorSpaceCreateDeviceRGB();auto ctx=CGBitmapContextCreate(raw.data(),w,h,8,w*4,color,kCGImageAlphaPremultipliedLast|kCGBitmapByteOrder32Big);CGColorSpaceRelease(color);if(!ctx)throw Error("当前内存不足以读取图片。");CGContextDrawImage(ctx,CGRectMake(0,0,w,h),image);CGContextRelease(ctx);Pixels p{w,h,alpha?4:3,{}};p.data.resize(size_t(w)*h*p.channels);for(size_t i=0;i<size_t(w)*h;i++){int a=raw[i*4+3];for(int c=0;c<3;c++)p.data[i*p.channels+c]=alpha?(a?std::min(255,(int(raw[i*4+c])*255+a/2)/a):0):uint8_t(std::min(255,int(raw[i*4+c])+255-a));if(alpha)p.data[i*4+3]=a;}return p;}
static Pixels loadCarrier(NSData* d){auto s=source(d);try{auto [w,h,o]=dimensions(s);if(uint64_t(w)*h>80000000||std::max(w,h)>20000)throw Error("底图最多8,000万像素，单边不超过20,000。");memoryCheck(uint64_t(w)*h*20+32000000);if(pngData(d)){CFRelease(s);s=nullptr;return loadPixels(dataBytes(d),3);}auto image=CGImageSourceCreateImageAtIndex(s,0,nullptr);CFRelease(s);s=nullptr;if(!image)throw Error("无法读取图片。");Pixels p;try{p=rendered(image,false);}catch(...){CGImageRelease(image);throw;}CGImageRelease(image);return p;}catch(...){if(s)CFRelease(s);throw;}}
static Pixels loadSecret(NSData* data){auto s=source(data);try{auto [w,h,o]=dimensions(s);double scale=std::min(1.,std::min(1920./std::max(w,h),1080./std::min(w,h)));if(scale==1&&o==1&&pngData(data)){memoryCheck(uint64_t(w)*h*16);CFRelease(s);s=nullptr;return loadPixels(dataBytes(data),4);}int target=std::max(1,int(std::floor(std::max(w,h)*scale)));NSDictionary* options=@{(__bridge NSString*)kCGImageSourceCreateThumbnailFromImageAlways:@YES,(__bridge NSString*)kCGImageSourceCreateThumbnailWithTransform:@YES,(__bridge NSString*)kCGImageSourceThumbnailMaxPixelSize:@(target),(__bridge NSString*)kCGImageSourceShouldCacheImmediately:@YES};auto image=CGImageSourceCreateThumbnailAtIndex(s,0,(__bridge CFDictionaryRef)options);CFRelease(s);s=nullptr;if(!image)throw Error("无法读取待加密图片。");Pixels p;try{p=rendered(image,true);}catch(...){CGImageRelease(image);throw;}CGImageRelease(image);return p;}catch(...){if(s)CFRelease(s);throw;}}
static Bytes jpeg(const Pixels& p,int quality){Bytes rgb(size_t(p.w)*p.h*3);for(size_t i=0;i<size_t(p.w)*p.h;i++){int a=p.channels==4?p.data[i*4+3]:255;for(int c=0;c<3;c++)rgb[i*3+c]=(int(p.data[i*p.channels+c])*a+255*(255-a)+127)/255;}NSData* raw=nsdata(rgb);auto provider=CGDataProviderCreateWithCFData((__bridge CFDataRef)raw);auto color=CGColorSpaceCreateDeviceRGB();auto image=CGImageCreate(p.w,p.h,8,24,p.w*3,color,kCGImageAlphaNone,provider,nullptr,false,kCGRenderingIntentDefault);CGColorSpaceRelease(color);CGDataProviderRelease(provider);if(!image)throw Error("图片转换失败。");NSMutableData* out=[NSMutableData data];auto dest=CGImageDestinationCreateWithData((__bridge CFMutableDataRef)out,(__bridge CFStringRef)UTTypeJPEG.identifier,1,nullptr);if(!dest){CGImageRelease(image);throw Error("JPG编码不可用。");}NSDictionary* opt=@{(__bridge NSString*)kCGImageDestinationLossyCompressionQuality:@(quality/100.)};CGImageDestinationAddImage(dest,image,(__bridge CFDictionaryRef)opt);bool ok=CGImageDestinationFinalize(dest);CFRelease(dest);CGImageRelease(image);if(!ok)throw Error("JPG压缩失败。");return dataBytes(out);}
static Pixels shrink(const Pixels& p){Pixels out{std::max(1,int(p.w*.85)),std::max(1,int(p.h*.85)),p.channels,{}};out.data.resize(size_t(out.w)*out.h*out.channels);for(int y=0;y<out.h;y++)for(int x=0;x<out.w;x++){double sx=(x+.5)*p.w/out.w-.5,sy=(y+.5)*p.h/out.h-.5;int x0=std::max(0,int(sx)),y0=std::max(0,int(sy)),x1=std::min(p.w-1,x0+1),y1=std::min(p.h-1,y0+1);double fx=std::max(0.,sx-x0),fy=std::max(0.,sy-y0);for(int c=0;c<p.channels;c++){auto sample=[&](int xx,int yy){return p.data[(size_t(yy)*p.w+xx)*p.channels+c];};out.data[(size_t(y)*out.w+x)*out.channels+c]=uint8_t(std::lround((sample(x0,y0)*(1-fx)+sample(x1,y0)*fx)*(1-fy)+(sample(x0,y1)*(1-fx)+sample(x1,y1)*fx)*fy));}}return out;}
static Prepared prepare(NSData* data,int capacity,bool png,const Progress& progress){auto p=loadSecret(data);if(png){auto out=writePNG(p);if(int(out.size())>capacity)throw Error("底图容量不足以容纳PNG无损图片。请选择更大的底图或改用JPG模式；无损模式不会额外缩小正文。");return {out,p.w,p.h,0,true};}for(;;){for(int q=85;q>=50;q-=5){if(progress)progress(1,"正在压缩图片…");auto out=jpeg(p,q);if(int(out.size())<=capacity)return {out,p.w,p.h,q,false};}if(p.w==1&&p.h==1)throw Error("底图空间不足。");p=shrink(p);}}
static Progress callback(BIPProgress p){return [p](int n,const std::string& t){if(p&&!p(n,[NSString stringWithUTF8String:t.c_str()]))throw Error("操作已取消。");};}
@implementation BIPService
+ (NSString*)generateKey {auto s=generateKey();return [NSString stringWithUTF8String:s.c_str()];}
+ (NSData*)backupKey:(NSString*)password salt:(NSData*)salt error:(NSError**)error {NSData* p=[password dataUsingEncoding:NSUTF8StringEncoding];uint8_t out[32];int status=CCKeyDerivationPBKDF(kCCPBKDF2,static_cast<const char*>(p.bytes),p.length,static_cast<const uint8_t*>(salt.bytes),salt.length,kCCPRFHmacAlgSHA256,210000,out,32);if(status){if(error)*error=[NSError errorWithDomain:@"binary_image_passcode" code:2 userInfo:@{NSLocalizedDescriptionKey:@"备份密码处理失败。"}];return nil;}return [NSData dataWithBytes:out length:32];}
+ (NSInteger)unitCount:(NSString*)text error:(NSError**)error {try{return units(utf16(text)).size();}catch(const std::exception& e){failure(error,e);return -1;}}
+ (BIPOutput*)encrypt:(NSData*)carrier secret:(NSData*)secret text:(NSString*)text key:(NSString*)key png:(BOOL)png strong:(BOOL)strong progress:(BIPProgress)progress error:(NSError**)error {try{std::string k=key.UTF8String;validateKey(k);auto p=loadCarrier(carrier);Image im(p.w,p.h,std::move(p.data));BIPOutput* result=[BIPOutput new];uint64_t seconds=uint64_t(NSDate.date.timeIntervalSince1970);auto nonce=randomBytes(48);auto cb=callback(progress);Bytes env;if(secret){auto prep=prepare(secret,png?denseCapacity(im.w,im.h):jpegCapacity(im.w,im.h,strong),png,cb);env=sealImage(prep,k,seconds,nonce);result.secretData=nsdata(prep.data);result.png=png;result.details=[NSString stringWithFormat:@"图片正文 %d×%d · %@ · %.1f KiB",prep.w,prep.h,png?@"PNG无损":@"JPG",prep.data.size()/1024.];}else{env=sealText(utf16(text),k,seconds,nonce);result.details=@"文字消息";}encode(im,env,k,strong,secret&&png,cb);if(cb)cb(97,"正在保存PNG…");result.carrierPNG=nsdata(writePNG({im.w,im.h,3,std::move(im.rgb)}));result.seconds=seconds;return result;}catch(const std::exception& e){failure(error,e);return nil;}}
+ (BIPOutput*)decrypt:(NSData*)carrier key:(NSString*)key progress:(BIPProgress)progress error:(NSError**)error {try{auto p=loadCarrier(carrier);Image im(p.w,p.h,std::move(p.data));auto r=decode(im,key.UTF8String,callback(progress));BIPOutput* out=[BIPOutput new];out.seconds=r.seconds;out.text=[[NSString alloc] initWithCharacters:reinterpret_cast<const unichar*>(r.text.data()) length:r.text.size()];if(!r.image.data.empty()){auto s=source(nsdata(r.image.data));auto image=CGImageSourceCreateImageAtIndex(s,0,nullptr);CFRelease(s);if(!image)throw Error("图片正文无法完整解码。");CGImageRelease(image);out.secretData=nsdata(r.image.data);out.png=r.image.png;}out.details=[NSString stringWithFormat:@"已通过完整性认证 · 数据块 %d/%d · 所需 %d · 纠正 %d 字节",r.recovered,r.total,r.required,r.corrected];return out;}catch(const std::exception& e){failure(error,e);return nil;}}
@end
